/**
 * @description 行政区域更新时的方法,现在行政区域从接口获取
 * - 根据新的行政区域更新另外2个下拉
 */
onCascaderChange() {
  this.syncRegionCodeName()
  this.getSubdistrictList(this.form.region) // 查询所属街道列表
},
/**
 * @description 补齐后端必填的行政区划编码/名称
 * - `region`(单一区划编码) 是该页面的行政区域字段；后端保存校验还要求 regionCode / regionName
 * - 原始数据无 regionCode 时，优先用 region 兜底；若有 projectId(complexId) 则查小区详情取 region；
 *   regionName 用全局行政区划(allAreas)按编码反查补齐
 */
syncRegionCodeName() {
  if (!this.form.regionCode) {
    this.form.regionCode = this.form.region
  }
  if (this.form.regionCode) {
    this.fillRegionNameByCode(this.form.regionCode)
  }
  if (this.form.regionCode && this.form.regionName) {
    return
  }
  // region / regionCode 均缺失时，用小区详情兜底
  const complexId = this.form.complexId || this.$route.query.complexId
  if (!complexId) {
    return
  }
  this.$get(`/${this.moduleName}/complex/${complexId}`).then((res) => {
    const row = res.data
    if (!row) {
      return
    }
    if (!this.form.regionCode) {
      this.form.regionCode = row.region
      this.form.region = this.form.region || row.region
    }
    if (this.form.regionCode) {
      this.fillRegionNameByCode(this.form.regionCode)
    }
  })
},
// 用全局行政区划反查区域全名，补齐 regionName
fillRegionNameByCode(code) {
  if (!code || this.form.regionName) {
    return
  }
  const regionName = getFullRegionNameByRegionCode(this.allAreas, code)
  if (regionName && !regionName.includes('undefined')) {
    this.form.regionName = regionName
  }
},

